const gujaratiDigits = '૦૧૨૩૪૫૬૭૮૯'

// Day/month/two-digit year, "09/10/26", as the app writes every date. With
// `localDigits` a Gujarati calendar shows Gujarati digits; the typed field keeps
// ASCII digits because its mask only knows those.
export function dayMonthYearFormatter(
  locale: string | undefined,
  localDigits: boolean
): { format: (date: Date) => string } {
  const two = (n: number) => String(n).padStart(2, '0')
  const gujarati = localDigits && !!locale && locale.startsWith('gu')
  return {
    format: (date: Date) => {
      const text = `${two(date.getDate())}/${two(date.getMonth() + 1)}/${two(
        date.getFullYear() % 100
      )}`
      return gujarati
        ? text.replace(/\d/g, (digit) => gujaratiDigits[Number(digit)])
        : text
    },
  }
}

export function useInputFormatter({ locale }: { locale: string | undefined }) {
  return useMemo(() => dayMonthYearFormatter(locale, false), [locale])
}

